-- Event 1: ZettaBlock Launches Open Beta with Sui Integration (March 5, 2024)
INSERT INTO events (id, date, title, summary, category, tags, mode, image, media, links, metrics)
VALUES (
  'zettablock-sui-open-beta-2024-03-05',
  '2024-03-05',
  'ZettaBlock Launches Open Beta with Sui as Foundational Partner',
  'Web3 data platform ZettaBlock launched its open beta on March 5, 2024, with Sui blockchain as one of twelve foundational network integrations. The platform enables developers to access real-time, on-chain data across multiple blockchains through a unified GraphQL API interface, eliminating the need for multiple data vendors. ZettaBlock''s full-stack platform merges on-chain historical and real-time data with private off-chain sources, empowering builders to quickly create custom APIs with no infrastructure overhead. The partnership marked a significant milestone for both the Sui ecosystem (which had recently broken into the top 10 chains by TVL) and Web3 interoperability.',
  '{"DeFi Protocol","Layer 2"}',
  '{"TECH","MILESTONE"}',
  '{"timeline"}',
  'https://pbs.twimg.com/media/GH8vsggaMAALRn8.jpg',
