-- Event 3: MEXC Lists iDOS Token with Multiple CEX Launch (March 5, 2026)
INSERT INTO events (id, date, title, summary, category, tags, mode, image, media, links, metrics)
VALUES (
  'mexc-idos-listing-multi-cex-launch-2026-03-05',
  '2026-03-05',
  'MEXC Lists iDOS Token as Part of Major Multi-CEX Launch',
  'MEXC officially listed $IDOS, the native token of idOS network (a portable identity protocol for the stablecoin economy), with IDOS/USDT spot trading commencing on March 5, 2026, at 14:00 UTC. The listing was part of a coordinated multi-exchange Token Generation Event (TGE) that also included simultaneous launches on Kraken, OKX, KuCoin, Gate.io, BingX, Bitget, and Bitmart. MEXC''s Convert feature for IDOS went live until March 6 at 14:00 UTC. The idOS project, backed by notable investors including Fabric Ventures, Arbitrum, and Circle, distributed tokens directly to linked wallet addresses without requiring an airdrop checker (except for Wallchain Quackers participants). The coordinated launch represented a major milestone for decentralized identity infrastructure in the DeFi ecosystem.',
